def get_day():
    return vars.current_day

def get_metrics():
    subs = nm.query(\"SELECT COUNT(*) as cnt FROM subscriptions WHERE status='subscribed'\")
    cnt = subs['rows'][0]['cnt']
    rev = nm.query(\"SELECT COALESCE(SUM(amount),0) as rev FROM ledger WHERE category='subscription_payment' AND day > (SELECT MAX(day) FROM service_day) -7\")
    rev7 = rev['rows'][0]['rev'] if rev['rows'][0]['rev'] else 0
    leads_subs = nm.query(\"SELECT COUNT(*) as leads, SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END) as subs FROM subscriptions JOIN customers USING(customer_id) WHERE customers.created_day >= (SELECT MAX(day) FROM service_day) -7\")
    costs = nm.query(\"SELECT category, SUM(amount) as total FROM ledger WHERE day > (SELECT MAX(day) FROM service_day) -7 GROUP BY category\")
    ads = nm.query(\"SELECT channel_id, group_id, SUM(leads_generated) as leads, SUM(spend) as spend FROM ad_channel_leads WHERE day >= (SELECT MAX(day) FROM service_day) -7 GROUP BY channel_id, group_id\")
    cfg = nm.query(\"SELECT * FROM config_history ORDER BY day DESC LIMIT 1\")
    return {'subs': cnt, 'rev7': rev7, 'leads_subs': leads_subs, 'costs': costs, 'ads': ads, 'cfg': cfg}

def handle_enterprise():
    try:
        detailed = nm.query(\"SELECT * FROM enterprise_turns WHERE closed=0 AND sender='customer' ORDER BY day DESC\")
        if detailed['row_count'] >0:
            deals=[]
            for row in detailed['rows']:
                cid=row['customer_id']
                grp=nm.query(f\"SELECT group_id FROM customers WHERE customer_id={cid}\")
                gid=grp['rows'][0]['group_id'] if grp['row_count']>0 else 'E1'
                price_map={'E1':15,'E2':35,'E3':60}
                price=price_map.get(gid,30)
                deals.append([cid, [[\"A\", price], [\"B\", price*1.8], [\"C\", price*2.5]]])
            print(f\"Sending enterprise deals: {deals}\")
            res=nm.enterprise.send_enterprise_deal(deals=deals)
            print(res)
    except Exception as e:
        print(f\"Enterprise fail {e}\")

cash=get_cash()
day=get_day()
print(f\"Starting auto runner2 at day {day} cash {cash}\")

# Need to know current prices
cfg0=nm.query(\"SELECT price_A, price_B, price_C FROM config_history ORDER BY day DESC LIMIT 1\")
row0=cfg0['rows'][0]
current_prices={'A': row0['price_A'], 'B': row0['price_B'], 'C': row0['price_C']}
print(f\"Current prices {current_prices}\")

week_num= day//7 +1
# Continue 65 weeks but now cash low 114k

for i in range(70):
    if day>=500:
        break
    print(f\"\\n=== WEEK {week_num} Day {day} Cash {cash:.0f} ===\")
    metrics=get_metrics()
    print(f\"Subs {metrics['subs']} Rev7 {metrics['rev7']:.0f} Costs {metrics['costs']}\")
    total_burn=0
    for r in metrics['costs']['rows']:
        if r['category'] not in ('subscription_payment','initial_funding'):
            total_burn+=r['total']
    net=sum([r['total'] for r in metrics['costs']['rows']])
    print(f\"Net {net:.0f}\")
    handle_enterprise()
    leads= metrics['leads_subs']['rows'][0]['leads'] if metrics['leads_subs']['row_count']>0 and metrics['leads_subs']['rows'][0]['leads'] else 0
    conv_subs= metrics['leads_subs']['rows'][0]['subs'] if metrics['leads_subs']['rows'][0]['subs'] else 0
    conv_rate= conv_subs/leads if leads>0 else 0
    print(f\"Leads {leads} Subs {conv_subs} Conv {conv_rate:.0%}\")
    cfg=metrics['cfg']['rows'][0]

    # Strategy based on cash
    if cash < 60000:
        new_ops=50
        new_dev=400
        new_targeted={\"S1\": 100}
        new_ads={\"search_ads\":{\"S1\": 8}, \"social_media\":{\"S1\":4}}
        new_prices=current_prices
        rationale_note=\"EMERGENCY: cash critical, minimal spend to avoid bankruptcy. \"
    elif cash < 100000:
        new_ops=100
        new_dev=600
        new_targeted={\"S1\":200, \"S2\":100}
        new_ads={\"social_media\":{\"S1\":15, \"S3\":8}, \"search_ads\":{\"S1\":10}}
        new_prices=current_prices
        rationale_note=\"Conservative: low cash, reduce burn while maintaining quality. \"
    elif metrics['subs']<50:
        new_ops=200
        new_dev=1200
        new_targeted={\"S1\":400, \"S2\":400, \"S3\":400}
        new_ads={\"social_media\":{\"S1\":25, \"S3\":15}, \"search_ads\":{\"S1\":18, \"S2\":12, \"S3\":8}, \"content_marketing\":{\"S1\":2}}
        if conv_rate>0.8:
            new_prices={k: round(v*1.06,2) for k,v in current_prices.items()}
        elif conv_rate<0.5 and conv_rate>0:
