        new_targeted={\"S1\":300, \"S2\":500, \"S3\":500}
        new_ads={\"social_media\":{\"S1\":30, \"S3\":20}, \"search_ads\":{\"S1\":20, \"S2\":15, \"S3\":10}}
        if conv_rate>0.7:
            new_prices={k: round(v*1.07,2) for k,v in current_prices.items()}
        elif conv_rate<0.45 and conv_rate>0:
            new_prices={k: round(v*0.97,2) for k,v in current_prices.items()}
        else:
            new_prices=current_prices
        rationale_note=\"Scaling to profitability: focus S2/S3 premium. \"
    else:
        new_ops=300
