        if conv_rate>0.65:
            new_prices={k: round(v*1.06,2) for k,v in current_prices.items()}
        else:
            new_prices=current_prices
        rationale_note=\"Mature harvest: push premium pricing. \"

    current_prices=new_prices
    print(f\"Applying ops {new_ops} dev {new_dev} targeted {new_targeted} ads {new_ads} prices {new_prices}\")
    try:
        print(nm.marketing.set_daily_spend(operations=new_ops, development=new_dev))
    except Exception as e:
        print(e)
    try:
        print(nm.analytics.set_targeted_dev_spend(targeted_spend=new_targeted))
    except Exception as e:
        print(e)
    try:
        print(nm.marketing.set_targeted_ad_spend(targeted_spend=new_ads))
    except Exception as e:
        print(e)
    try:
        print(nm.pricing.set_prices(A=new_prices['A'], B=new_prices['B'], C=new_prices['C']))
    except Exception as e:
        print(e)

    # R&D management: only if cash >150k and no more than 2 parallel
    try:
        rp=nm.research.list_research_projects()
        # Count in_progress
        inprog=sum(1 for t in rp['tiers'] if t['in_progress']==1)
        # If tier2 still in progress, don't start expensive tiers unless cash high
        # Only start new tier if cash > tier cost + 80k buffer and inprog <2
        if inprog <2 and cash > 200000:
            # prioritize tier3 then tier4 etc
            for t in sorted(rp['tiers'], key=lambda x: x['tier']):
                if t['in_progress']==0 and t['tier'] not in [1]: # avoid tier1 repeat too often
                    # Check if tier already completed once, we can repeat but less priority
                    if t['tier']==3 and t['completed']==0 and cash > 600000:
                        print(f\"Attempt start tier {t['tier']}\")
                        try:
                            print(nm.research.start_research_project(tier=t['tier']))
                            break
                        except Exception as e:
                            print(e)
                    elif t['tier']>3 and cash>800000:
                        pass
            # If tier1 not in progress and completed and cash>200k and inprog<1, restart tier1 cheap booster
            tier1=[x for x in rp['tiers'] if x['tier']==1][0]
            if tier1['in_progress']==0 and inprog==0 and cash>180000:
                print(\"Restart tier1\")
                try:
                    print(nm.research.start_research_project(tier=1))
                except Exception as e:
                    print(e)
    except Exception as e:
        print(f\"R&D check {e}\")

    # Forecasts with fixed logic to avoid negative lower > upper
    # Use simple projection but ensure sane bounds
    proj_1wk = cash + net if net else cash-15000
    proj_4wk = cash + net*4 if net else cash-60000
    proj_12wk = cash + net*12 if net else cash-100000
    proj_26wk = cash + net*26 if net else cash-150000
    # Clamp projections to not go below 0 drastically, but allow low
    # For CI, ensure lower <= point <= upper with increasing width
    def make_forecast(point):
        # Ensure point is finite
        point = float(point)
        # If point very low negative, clamp to reasonable low but keep ordering
        # We'll set CI as point ± pct
        return point

    def ci(point, pct):
        # pct as fraction for both lower/upper, but ensure ordering
        # point could be negative, then lower should be more negative, upper less negative
        # e.g., point -1000, lower = -1500, upper = -500 -> lower < point < upper correct
        # Calculate lower = point - abs(point)*pct - 5000? Actually for negative, subtracting abs makes more negative (correct lower)
        # For positive, lower = point*(1-pct), upper = point*(1+pct)
        if point >=0:
            lower = point*(1-pct)
            upper = point*(1+pct)
        else:
            # point negative: lower more negative, upper less negative
            abs_point = abs(point)
            lower = point - abs_point*pct
            upper = point + abs_point*pct
            # Ensure lower < point < upper even when point negative
            # If upper crosses zero, that's okay but point negative upper could be negative or positive
        # Ensure lower <= point <= upper
        if lower > point:
            lower = point - abs(point)*pct - 1000 if point"'!=0 else point-5000
        if upper < point:
            upper = point + abs(point)*pct + 1000 if point!=0 else point+5000
        # Clamp lower to not extremely negative? Keep as is but ensure valid numbers
        # Ensure lower <= upper
        if lower > upper:
            lower, upper = min(lower, upper), max(lower, upper)
        # Round
        return int(round(point)), int(round(lower)), int(round(upper))

    p1,l1,u1 = ci(proj_1wk, 0.15)
    p4,l4,u4 = ci(proj_4wk, 0.30)
