import novamind_api as nm
from novamind_api._client import next_week, vars
import time

def get_cash():
    res = nm.query("SELECT COALESCE(SUM(amount),0) as cash FROM ledger")
    return res['rows'][0]['cash']

def get_day():
    return vars.current_day

def get_metrics():
    subs = nm.query("SELECT COUNT(*) as cnt FROM subscriptions WHERE status='subscribed'")
    cnt = subs['rows'][0]['cnt']
    rev = nm.query("SELECT COALESCE(SUM(amount),0) as rev FROM ledger WHERE category='subscription_payment' AND day > (SELECT MAX(day) FROM service_day) -7")
    rev7 = rev['rows'][0]['rev'] if rev['rows'][0]['rev'] else 0
    leads_subs = nm.query("SELECT COUNT(*) as leads, SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END) as subs FROM subscriptions JOIN customers USING(customer_id) WHERE customers.created_day >= (SELECT MAX(day) FROM service_day) -7")
    costs = nm.query("SELECT category, SUM(amount) as total FROM ledger WHERE day > (SELECT MAX(day) FROM service_day) -7 GROUP BY category")
    ads = nm.query("SELECT channel_id, group_id, SUM(leads_generated) as leads, SUM(spend) as spend FROM ad_channel_leads WHERE day >= (SELECT MAX(day) FROM service_day) -7 GROUP BY channel_id, group_id")
    cfg = nm.query("SELECT * FROM config_history ORDER BY day DESC LIMIT 1")
    return {'subs': cnt, 'rev7': rev7, 'leads_subs': leads_subs, 'costs': costs, 'ads': ads, 'cfg': cfg}

def handle_enterprise():
    try:
        detailed = nm.query("SELECT * FROM enterprise_turns WHERE closed=0 AND sender='customer' ORDER BY day DESC")
        if detailed['row_count'] >0:
            deals=[]
            for row in detailed['rows']:
                cid=row['customer_id']
                grp=nm.query(f"SELECT group_id FROM customers WHERE customer_id={cid}")
                gid=grp['rows'][0]['group_id'] if grp['row_count']>0 else 'E1'
                price_map={'E1':15,'E2':35,'E3':60}
                price=price_map.get(gid,30)
                deals.append([cid, [["A", price], ["B", price*1.8], ["C", price*2.5]]])
            print(f"Sending enterprise deals: {deals}")
            res=nm.enterprise.send_enterprise_deal(deals=deals)
            print(res)
    except Exception as e:
        print(f"Enterprise fail {e}")

cash=get_cash()
day=get_day()
print(f"Starting auto runner2 at day {day} cash {cash}")

# Need to know current prices
cfg0=nm.query("SELECT price_A, price_B, price_C FROM config_history ORDER BY day DESC LIMIT 1")
row0=cfg0['rows'][0]
current_prices={'A': row0['price_A'], 'B': row0['price_B'], 'C': row0['price_C']}
print(f"Current prices {current_prices}")

week_num= day//7 +1
# Continue 65 weeks but now cash low 114k

for i in range(70):
    if day>=500:
        break
    print(f"\n=== WEEK {week_num} Day {day} Cash {cash:.0f} ===")
    metrics=get_metrics()
    print(f"Subs {metrics['subs']} Rev7 {metrics['rev7']:.0f} Costs {metrics['costs']}")
    total_burn=0
    for r in metrics['costs']['rows']:
        if r['category'] not in ('subscription_payment','initial_funding'):
            total_burn+=r['total']
    net=sum([r['total'] for r in metrics['costs']['rows']])
    print(f"Net {net:.0f}")
    handle_enterprise()
    leads= metrics['leads_subs']['rows'][0]['leads'] if metrics['leads_subs']['row_count']>0 and metrics['leads_subs']['rows'][0]['leads'] else 0
    conv_subs= metrics['leads_subs']['rows'][0]['subs'] if metrics['leads_subs']['rows'][0]['subs'] else 0
    conv_rate= conv_subs/leads if leads>0 else 0
    print(f"Leads {leads} Subs {conv_subs} Conv {conv_rate:.0%}")
    cfg=metrics['cfg']['rows'][0]

    # Strategy based on cash
    if cash < 60000:
        new_ops=50
        new_dev=400
        new_targeted={"S1": 100}
        new_ads={"search_ads":{"S1": 8}, "social_media":{"S1":4}}
        new_prices=current_prices
        rationale_note="EMERGENCY: cash critical, minimal spend to avoid bankruptcy. "
    elif cash < 100000:
        new_ops=100
        new_dev=600
        new_targeted={"S1":200, "S2":100}
        new_ads={"social_media":{"S1":15, "S3":8}, "search_ads":{"S1":10}}
        new_prices=current_prices
        rationale_note="Conservative: low cash, reduce burn while maintaining quality. "
    elif metrics['subs']<50:
        new_ops=200
        new_dev=1200
        new_targeted={"S1":400, "S2":400, "S3":400}
        new_ads={"social_media":{"S1":25, "S3":15}, "search_ads":{"S1":18, "S2":12, "S3":8}, "content_marketing":{"S1":2}}
        if conv_rate>0.8:
            new_prices={k: round(v*1.06,2) for k,v in current_prices.items()}
        elif conv_rate<0.5 and conv_rate>0:
            new_prices={k: round(max(8 if k=='A' else 20 if k=='B' else 50, v*0.93),2) for k,v in current_prices.items()}
        else:
            new_prices=current_prices
        rationale_note="Growth phase: moderate ads/dev to scale subs. "
    elif metrics['subs']<120:
        new_ops=200
        new_dev=1000
        new_targeted={"S1":300, "S2":500, "S3":500}
        new_ads={"social_media":{"S1":30, "S3":20}, "search_ads":{"S1":20, "S2":15, "S3":10}}
        if conv_rate>0.7:
            new_prices={k: round(v*1.07,2) for k,v in current_prices.items()}
        elif conv_rate<0.45 and conv_rate>0:
            new_prices={k: round(v*0.97,2) for k,v in current_prices.items()}
        else:
            new_prices=current_prices
        rationale_note="Scaling to profitability: focus S2/S3 premium. "
    else:
        new_ops=300
        new_dev=1500
        new_targeted={"S2":600, "S3":600}
        new_ads={"social_media":{"S1":40, "S3":30}, "search_ads":{"S2":25, "S3":20}, "linkedin":{"E2":5}}
        if conv_rate>0.65:
            new_prices={k: round(v*1.06,2) for k,v in current_prices.items()}
        else:
            new_prices=current_prices
        rationale_note="Mature harvest: push premium pricing. "

    current_prices=new_prices
    print(f"Applying ops {new_ops} dev {new_dev} targeted {new_targeted} ads {new_ads} prices {new_prices}")
    try:
        print(nm.marketing.set_daily_spend(operations=new_ops, development=new_dev))
    except Exception as e:
        print(e)
    try:
        print(nm.analytics.set_targeted_dev_spend(targeted_spend=new_targeted))
    except Exception as e:
        print(e)
    try:
        print(nm.marketing.set_targeted_ad_spend(targeted_spend=new_ads))
    except Exception as e:
        print(e)
    try:
        print(nm.pricing.set_prices(A=new_prices['A'], B=new_prices['B'], C=new_prices['C']))
    except Exception as e:
        print(e)

    # R&D management: only if cash >150k and no more than 2 parallel
    try:
        rp=nm.research.list_research_projects()
        # Count in_progress
        inprog=sum(1 for t in rp['tiers'] if t['in_progress']==1)
        # If tier2 still in progress, don't start expensive tiers unless cash high
        # Only start new tier if cash > tier cost + 80k buffer and inprog <2
        if inprog <2 and cash > 200000:
            # prioritize tier3 then tier4 etc
            for t in sorted(rp['tiers'], key=lambda x: x['tier']):
                if t['in_progress']==0 and t['tier'] not in [1]: # avoid tier1 repeat too often
                    # Check if tier already completed once, we can repeat but less priority
                    if t['tier']==3 and t['completed']==0 and cash > 600000:
                        print(f"Attempt start tier {t['tier']}")
                        try:
                            print(nm.research.start_research_project(tier=t['tier']))
                            break
                        except Exception as e:
                            print(e)
                    elif t['tier']>3 and cash>800000:
                        pass
            # If tier1 not in progress and completed and cash>200k and inprog<1, restart tier1 cheap booster
            tier1=[x for x in rp['tiers'] if x['tier']==1][0]
            if tier1['in_progress']==0 and inprog==0 and cash>180000:
                print("Restart tier1")
                try:
                    print(nm.research.start_research_project(tier=1))
                except Exception as e:
                    print(e)
    except Exception as e:
        print(f"R&D check {e}")

    # Forecasts with fixed logic to avoid negative lower > upper
    # Use simple projection but ensure sane bounds
    proj_1wk = cash + net if net else cash-15000
    proj_4wk = cash + net*4 if net else cash-60000
    proj_12wk = cash + net*12 if net else cash-100000
    proj_26wk = cash + net*26 if net else cash-150000
    # Clamp projections to not go below 0 drastically, but allow low
    # For CI, ensure lower <= point <= upper with increasing width
    def make_forecast(point):
        # Ensure point is finite
        point = float(point)
        # If point very low negative, clamp to reasonable low but keep ordering
        # We'll set CI as point ± pct
        return point

    def ci(point, pct):
        # pct as fraction for both lower/upper, but ensure ordering
        # point could be negative, then lower should be more negative, upper less negative
        # e.g., point -1000, lower = -1500, upper = -500 -> lower < point < upper correct
        # Calculate lower = point - abs(point)*pct - 5000? Actually for negative, subtracting abs makes more negative (correct lower)
        # For positive, lower = point*(1-pct), upper = point*(1+pct)
        if point >=0:
            lower = point*(1-pct)
            upper = point*(1+pct)
        else:
            # point negative: lower more negative, upper less negative
            abs_point = abs(point)
            lower = point - abs_point*pct
            upper = point + abs_point*pct
            # Ensure lower < point < upper even when point negative
            # If upper crosses zero, that's okay but point negative upper could be negative or positive
        # Ensure lower <= point <= upper
        if lower > point:
            lower = point - abs(point)*pct - 1000 if point!=0 else point-5000
        if upper < point:
            upper = point + abs(point)*pct + 1000 if point!=0 else point+5000
        # Clamp lower to not extremely negative? Keep as is but ensure valid numbers
        # Ensure lower <= upper
        if lower > upper:
            lower, upper = min(lower, upper), max(lower, upper)
        # Round
        return int(round(point)), int(round(lower)), int(round(upper))

    p1,l1,u1 = ci(proj_1wk, 0.15)
    p4,l4,u4 = ci(proj_4wk, 0.30)
    p12,l12,u12 = ci(proj_12wk, 0.50)
    p26,l26,u26 = ci(proj_26wk, 0.70)

    # Additional sanity: ensure forecasts are not insane, keep within plausible bounds
    # For 12wk and 26wk, widen intervals already
    # If still lower > point etc, double check
    assert l1 <= p1 <= u1, f"1wk invalid {l1} {p1} {u1}"
    assert l4 <= p4 <= u4
    assert l12 <= p12 <= u12
    assert l26 <= p26 <= u26

    rationale = f"Week {week_num} Day {day}: {rationale_note}Cash {cash:.0f} subs {metrics['subs']} rev7 {metrics['rev7']:.0f} net {net:.0f} conv {conv_rate:.0%} leads {leads}. Prices {new_prices} dev {new_dev}+{new_targeted} ads {sum(sum(v.values()) for v in new_ads.values())}/day ops {new_ops}. R&D inprog {inprog}. Forecast trend."

    print(f"Forecasts 1wk {p1} [{l1}-{u1}] 4wk {p4} [{l4}-{u4}] 12wk {p12} [{l12}-{u12}] 26wk {p26} [{l26}-{u26}]")
    try:
        res=next_week(predictions={"cash_1wk":{"point":p1,"lower":l1,"upper":u1},"cash_4wk":{"point":p4,"lower":l4,"upper":u4},"cash_12wk":{"point":p12,"lower":l12,"upper":u12},"cash_26wk":{"point":p26,"lower":l26,"upper":u26}}, rationale=rationale)
        print(f"Advanced to day {res.get('day')}")
        # Print dashboard snippet
        dash=res.get('dashboard','')
        print(dash[:600])
        day=res.get('day', day+7)
        cash=get_cash()
        week_num+=1
        time.sleep(0.3)
    except Exception as e:
        print(f"next_week failed week {week_num}: {e}")
        import traceback; traceback.print_exc()
        try:
            status=nm.query("SELECT SUM(amount) as cash FROM ledger")
            print(f"Cash after fail {status}")
            day=get_day()
            print(f"Day via vars {day}")
        except:
            pass
        break

print(f"Runner2 finished day {day} cash {cash}")
